using System.Collections.Generic;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PredictionConvergence", menuName = "Data/Battle/Battle Actions/Orion/PredictionConvergence Action")]
public class PredictionConvergenceAction : StarRequirementAction
{
	[Header("Event")]
	[SerializeField]
	private ListDiceInstanceEvent OnDiscardUsedDicesWithoutExhaust;

	[Header("Dice Pools")]
	[SerializeField]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private PlayerDiceInventoryData discard;

	[Header("Astrium")]
	[SerializeField]
	private DefaultEffectAction gainAstriumAction;

	[Header("Move Orbs")]
	[SerializeField]
	private int moveOrbAmount = 1;

	[SerializeField]
	private BattleAction moveOrbsAction;

	public DefaultEffectAction GainAstriumAction => gainAstriumAction;

	public int MoveOrbAmount => moveOrbAmount;

	public BattleAction MoveOrbsAction => moveOrbsAction;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (!base.CheckConditionToBeCasted(playerHand, diceOwnerEnum))
		{
			return false;
		}
		if (playerHand)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > 1;
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > 0;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		List<DiceInstance> list = new List<DiceInstance>();
		list.AddRange(ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices);
		DiceInstance item = ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance;
		list.Remove(item);
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		gainAstriumAction.DefaultCast(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, list.Count * amount, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
		int num;
		if (dicePool.GetDicesAmount() <= 0)
		{
			num = ((discard.GetDicesAmount() > 0) ? 1 : 0);
			if (num == 0)
			{
				goto IL_008a;
			}
		}
		else
		{
			num = 1;
		}
		ReferenceSingleton<DiceDrawingHandler>.Instance.DrawActionCast(list.Count);
		goto IL_008a;
		IL_008a:
		OnDiscardUsedDicesWithoutExhaust.Raise(list);
		moveOrbsAction.CastAmount(moveOrbAmount, source);
		if (num == 0)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
	}
}
